package com.livetype.remote.core.pairing

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Shape of the QR payload generated by LiveType Bridge on Windows. */
@Serializable
private data class QrPayload(
    val v: Int? = null,
    val app: String? = null,
    val ws: String? = null,
    val host: String? = null,
    val port: Int? = null,
    val sid: String? = null,
    val pin: String? = null,
    val exp: Long? = null,
)

sealed interface QrParseResult {
    data class Ok(val info: PairingInfo) : QrParseResult
    data class Invalid(val reason: QrError) : QrParseResult
}

enum class QrError {
    NOT_JSON,
    WRONG_APP,
    EXPIRED,
    BAD_PIN,
    BAD_ADDRESS,
    MISSING_FIELDS,
}

/** Everything the app needs to reach and pair with the Windows bridge. */
data class PairingInfo(
    val wsUrl: String,
    val host: String,
    val port: Int,
    val sessionId: String,
    val pin: String,
    val expiresAtMs: Long,
) {
    val isValidNow: Boolean get() = System.currentTimeMillis() < expiresAtMs
}

object QrPayloadParser {

    private val json = Json { ignoreUnknownKeys = true }
    private val pinRegex = Regex("^\\d{6}$")

    fun parse(raw: String, nowMs: Long = System.currentTimeMillis()): QrParseResult {
        val payload = try {
            json.decodeFromString(QrPayload.serializer(), raw)
        } catch (_: Exception) {
            return QrParseResult.Invalid(QrError.NOT_JSON)
        }

        if (!payload.app.equals("LiveTypeBridge", ignoreCase = true)) {
            return QrParseResult.Invalid(QrError.WRONG_APP)
        }

        val host = payload.host?.trim().orEmpty()
        val port = payload.port ?: 0
        val sid = payload.sid?.trim().orEmpty()
        val pin = payload.pin?.trim().orEmpty()
        val exp = payload.exp ?: 0L

        if (host.isEmpty() || port !in 1..65535 || sid.isEmpty()) {
            return QrParseResult.Invalid(QrError.MISSING_FIELDS)
        }
        if (!pinRegex.matches(pin)) return QrParseResult.Invalid(QrError.BAD_PIN)
        if (exp <= nowMs) return QrParseResult.Invalid(QrError.EXPIRED)

        val url = payload.ws?.takeIf { it.isNotBlank() } ?: "ws://$host:$port/livetype"
        if (!url.startsWith("ws://")) return QrParseResult.Invalid(QrError.BAD_ADDRESS)

        return QrParseResult.Ok(PairingInfo(url, host, port, sid, pin, exp))
    }

    /** Builds a PairingInfo from the manual-entry form (same validation as QR). */
    fun fromManual(host: String, port: Int, sessionId: String, pin: String, expiresAtMs: Long): QrParseResult {
        val h = host.trim()
        val s = sessionId.trim()
        val p = pin.trim()
        return when {
            h.isEmpty() || port !in 1..65535 || s.isEmpty() -> QrParseResult.Invalid(QrError.MISSING_FIELDS)
            !pinRegex.matches(p) -> QrParseResult.Invalid(QrError.BAD_PIN)
            expiresAtMs in 1..System.currentTimeMillis() -> QrParseResult.Invalid(QrError.EXPIRED)
            else -> QrParseResult.Ok(PairingInfo("ws://$h:$port/livetype", h, port, s, p, expiresAtMs))
        }
    }
}
